    def __init__(self, base_field, *, delimiter=',', max_length=None, min_length=None, **kwargs):
    def clean(self, value):
    def prepare_value(self, value):
    def to_python(self, value):
    def validate(self, value):
    def run_validators(self, value):
    def has_changed(self, initial, data):
class SplitArrayWidget(forms.Widget):
    def __init__(self, widget, size, **kwargs):
    def is_hidden(self):
    def value_from_datadict(self, data, files, name):
    def value_omitted_from_data(self, data, files, name):
    def id_for_label(self, id_):
    def get_context(self, name, value, attrs=None):
    def media(self):
    def __deepcopy__(self, memo):
    def needs_multipart_form(self):
class SplitArrayField(forms.Field):
    def __init__(self, base_field, size, *, remove_trailing_nulls=False, **kwargs):
    def _remove_trailing_nulls(self, values):
    def to_python(self, value):
    def clean(self, value):
    def has_changed(self, initial, data):

Localization notes:
- get_context: SplitArrayWidget.get_context is called to render a list of checkboxes with initial data (e.g., `[False, True, False]`). → It creates a single `final_attrs` dictionary to be used for all subwidgets. → It loops through the data, calling `self.widget.get_context` (which is `CheckboxInput.get_context`) for each item, passing the *same* `final_attrs` dictionary instance each time. → When `CheckboxInput.get_context` receives a `True` value, it modifies the passed-in `final_attrs` dictionary by adding `'checked': True`. → For all subsequent iterations of the loop, `CheckboxInput.get_context` receives the `final_attrs` dictionary which now contains `'checked': True`, causing all following checkboxes to be rendered as checked, regardless of their actual value.
Ruled out:
- <module>: ruled out; the true cause is upstream.

